-- =====================================================================================
-- Surgical clinical decision support — 147 authored rules across all fifteen surgical
-- specialties, loaded as INSPECTABLE, NON-EXECUTABLE governance content.
--
-- Source: docs/clinical/surgical-domain-pack/rule-fragments/*.jsonl (15 files, wave SB-4).
-- Those fragments are the authored artifact; this migration is a faithful load of them and
-- adds no clinical content of its own.
--
-- ── WHAT THESE ROWS CAN AND CANNOT DO ───────────────────────────────────────────────
-- They cannot fire. That is deliberate, and it is enforced four independent ways:
--
--   1. `logic_json` and `logic_expression` are both NULL. The authored `logic` field is
--      English prose describing a condition, not a predicate tree. PredicateEvaluator has a
--      closed operator set and there is nothing here for it to evaluate. Prose is loaded into
--      `explanation_template`, where it is a description; it is never presented as logic.
--   2. `effective_start` is set beyond any operational horizon, so
--      RuleDefinitionEntity.activeOn() is false for every one of these rows. "Not ratified"
--      is therefore enforced by the same mechanism that retires a rule, not merely asserted
--      in a status column. Ratification replaces it with a real date.
--   3. `approval_status = ENGINEERING_SEED` with `adaptation_authority` naming the pending
--      authority. This content is engineering-authored and has NOT been reviewed by MoHCC.
--   4. RuleGovernanceService.apply() only adjusts alerts the deterministic engine has already
--      emitted, matched by `code`. No engine emits a SURG_* code, so these rows change no
--      behaviour anywhere today.
--
-- `interruptive = false` and `override_allowed = true` on every row, so even if a future
-- engine did emit one of these codes, it could not block care.
--
-- ── MAPPING DECISIONS, AND THE ONE THAT IS A DEFAULT RATHER THAN A JUDGEMENT ─────────
-- `code` is the fragment `rule_key` with hyphens as underscores (SURG-GS-01 -> SURG_GS_01).
-- `code` is globally UNIQUE across the whole table, so the SURG_ prefix is what keeps this
-- pack from colliding with another lane's rules.
--
-- `severity` is NOT NULL and the fragments do not carry it. It is derived from `layer`
-- (DANGER_SIGN -> HIGH, everything else -> MEDIUM). That is an ENGINEERING DEFAULT, not a
-- clinical judgement the authors supplied, and every row records that in `source_refs_json`
-- so ratification can see exactly which fields still need a clinician. Deriving a finer
-- gradation would fabricate precision nobody authored.
--
-- `message_template` is NOT NULL and takes the rule title; the authored `action` prose goes
-- to `required_action`, which is the column meant for what the clinician must do.
--
-- Migration band: this programme owns V300-V329 in clinical-knowledge-platform-service.
-- V200-V202 are the emergency lane's and V041 is RMNP's.
-- =====================================================================================

INSERT INTO clinical.rule_definitions (
    code, name, rule_type, trigger_context, layer,
    severity, message_template, explanation_template, required_action,
    interruptive, override_allowed,
    effective_start, version,
    approval_status, adaptation_authority,
    logic_expression, logic_json,
    source_refs_json
) VALUES
('SURG_BE_01', 'Laterality confirmed and marked for every breast and neck case', 'SURGICAL', 'breast_endocrine', 'DATA_VALIDATION', 'MEDIUM', 'Laterality confirmed and marked for every breast and neck case', 'If a unilateral breast or thyroid procedure is booked and the operative side is not recorded as marked and cross-checked against imaging, biopsy report, and consent, the case must not proceed to time-out completion.', 'Block operative-record progression until side-marking and three-source concordance (imaging, histology/cytology, consent) are captured; discordance escalates to the operating surgeon before anaesthesia.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_02', 'Euthyroid state gates thyroid surgery', 'SURGICAL', 'breast_endocrine', 'DATA_VALIDATION', 'MEDIUM', 'Euthyroid state gates thyroid surgery', 'If thyroidectomy is booked for a patient with current or previous thyrotoxicosis and no recent thyroid function result confirming euthyroid state is attached, the booking is incomplete — operating on the toxic gland risks thyroid storm.', 'Flag the booking; require a recent thyroid function result or documented endocrine/senior sign-off before the case is listed.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_03', 'Triple assessment completes before breast cancer surgery', 'SURGICAL', 'breast_endocrine', 'CLASSIFICATION', 'MEDIUM', 'Triple assessment completes before breast cancer surgery', 'If a breast lesion is on a surgical pathway for suspected carcinoma, it is classified surgery-ready only when clinical examination, imaging, and core needle biopsy results are all recorded and concordant, and an MDT (or documented senior surgical) decision exists; discordant triple assessment is classified unresolved.', 'Hold definitive cancer surgery listing until triple assessment concordance and a decision record exist; route discordant assessments back to the breast clinic for repeat biopsy or excision-biopsy decision.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_04', 'Post-thyroidectomy neck swelling is an airway emergency', 'SURGICAL', 'breast_endocrine', 'DANGER_SIGN', 'HIGH', 'Post-thyroidectomy neck swelling is an airway emergency', 'If a patient after thyroidectomy or neck exploration develops neck swelling, wound tension, stridor, voice change with distress, or difficulty breathing, a compressive haematoma is presumed.', 'Trigger emergency response: open the wound at the bedside (skin and strap closure) without waiting for theatre if airway compromise is present, call anaesthetics and the surgeon simultaneously, and return to theatre for haemostasis; keep clip/suture removers at the bedside for 24 hours postoperatively as standing policy.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_05', 'Non-resolving breast abscess or inflammatory change needs biopsy', 'SURGICAL', 'breast_endocrine', 'DANGER_SIGN', 'HIGH', 'Non-resolving breast abscess or inflammatory change needs biopsy', 'If a treated breast abscess or mastitis has not resolved after two aspiration/antibiotic cycles or 2 weeks, or a residual mass or persistent skin changes (peau d''orange, fixed erythema) are recorded, inflammatory carcinoma and tuberculosis are the presumptions to exclude.', 'Alert the clinician to arrange imaging plus core biopsy of the wall/mass and mycobacterial studies; block further repeat-aspiration-only plans without a biopsy decision recorded.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_06', 'Prophylaxis proportionate to clean breast and endocrine surgery', 'SURGICAL', 'breast_endocrine', 'THERAPY', 'MEDIUM', 'Prophylaxis proportionate to clean breast and endocrine surgery', 'If a clean breast or thyroid procedure is booked, a single intravenous dose of cefazolin within 60 minutes before incision is appropriate where drains, implants, axillary dissection, or prolonged surgery are anticipated; minor clean excisions without these factors may proceed without prophylaxis per unit policy; abscess surgery uses treatment antibiotics targeting staphylococci instead.', 'Prompt a proportionate prophylaxis decision at induction (single dose, none-with-reason, or treatment course) and record it; flag repeated postoperative dosing after clean surgery as non-indicated.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_07', 'Calcium surveillance after total thyroidectomy', 'SURGICAL', 'breast_endocrine', 'MONITORING', 'MEDIUM', 'Calcium surveillance after total thyroidectomy', 'If a total or completion thyroidectomy is performed, serum calcium must be checked per protocol within the first 24 hours and before discharge, with symptom checks (perioral tingling, carpopedal spasm) each nursing shift; symptomatic or falling calcium requires replacement and endocrine-pathway escalation.', 'Auto-generate calcium blood-draw tasks and per-shift symptom checks for 48 hours; alert the team on symptomatic hypocalcaemia or a falling trend; block discharge sign-off until a calcium result and replacement plan (or explicit none-needed) are recorded.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_08', 'Drain and seroma pathway after mastectomy', 'SURGICAL', 'breast_endocrine', 'MONITORING', 'MEDIUM', 'Drain and seroma pathway after mastectomy', 'If closed-suction drains are placed at mastectomy or axillary clearance, output is charted daily and drains removed per unit volume threshold; after removal, symptomatic seroma is managed by clinic aspiration, not readmission or re-operation.', 'Generate daily drain-output tasks with the removal threshold displayed; on removal, attach seroma-aspiration access instructions to the discharge plan and book the wound review.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_09', 'Breast cancer surveillance after curative surgery', 'SURGICAL', 'breast_endocrine', 'FOLLOW_UP', 'MEDIUM', 'Breast cancer surveillance after curative surgery', 'If curative breast cancer surgery is complete, follow-up requires: MDT review of final histology within 4 weeks driving adjuvant therapy; clinical review 6-monthly for 5 years then annually; annual surveillance mammography of conserved/contralateral breast where imaging capacity allows; and immediate re-referral criteria (new lump, skin change, arm swelling) on the discharge summary.', 'Auto-generate the surveillance schedule at histology sign-off; flag any patient whose adjuvant decision (radiotherapy after conservation especially) has no recorded plan within 6 weeks of surgery.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_BE_10', 'Thyroid histology and function follow-through', 'SURGICAL', 'breast_endocrine', 'FOLLOW_UP', 'MEDIUM', 'Thyroid histology and function follow-through', 'If any thyroid resection is performed, follow-up requires histology review with a completion-surgery decision where malignant; thyroid function testing at 6 weeks after hemithyroidectomy; and lifelong levothyroxine with periodic function testing after total thyroidectomy.', 'Open a histology-tracking task at operation coding; auto-book the 6-week function test; create the recurring levothyroxine monitoring task for total thyroidectomy patients.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/breast_endocrine-rules.jsonl","rule_key":"SURG-BE-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_01', 'Tension pneumothorax recognition', 'SURGICAL', 'cardiothoracic', 'DANGER_SIGN', 'HIGH', 'Tension pneumothorax recognition', 'Respiratory distress AND unilateral absent breath sounds AND (tracheal deviation away, distended neck veins, hypotension or rising airway pressures in the ventilated patient)', 'Do NOT wait for imaging: immediate needle decompression then finger/tube thoracostomy; document time and response; a chest radiograph of a tension pneumothorax is a process failure', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_02', 'Massive haemothorax threshold', 'SURGICAL', 'cardiothoracic', 'DANGER_SIGN', 'HIGH', 'Massive haemothorax threshold', 'Initial chest-drain output greater than ~1500 ml, or ongoing loss greater than ~200 ml/hour for 2-4 hours, or physiological deterioration with continuing drainage', 'Activate massive-transfusion response and thoracotomy pathway; notify the most senior surgeon available and the referral thoracic service; do not clamp the drain to ''tamponade'' the chest — clamping hides, not stops, the bleeding', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_03', 'Cardiac tamponade physiology', 'SURGICAL', 'cardiothoracic', 'DANGER_SIGN', 'HIGH', 'Cardiac tamponade physiology', 'Hypotension with raised venous pressure/distended neck veins, muffled heart sounds, pulsus paradoxus, or echo showing effusion with diastolic collapse — especially with TB history, malignancy or penetrating chest trauma', 'Emergency decompression pathway: echo-guided pericardiocentesis where skills/equipment exist, surgical window otherwise; anaesthetic induction before decompression is a recognised arrest trigger — sequence the theatre plan accordingly', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_04', 'Empyema staging drives the intervention', 'SURGICAL', 'cardiothoracic', 'CLASSIFICATION', 'MEDIUM', 'Empyema staging drives the intervention', 'Pleural sepsis recorded without a stage: exudative (free-flowing), fibrinopurulent (loculated pus), or organised (thick peel, trapped lung)', 'Prompt staging from ultrasound/radiograph and drainage behaviour at each review; exudative/fibrinopurulent stages route to drainage (with fibrinolytics where stocked), organised stage routes to decortication referral — an undrained loculated empyema on prolonged antibiotics is a stalled pathway', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_05', 'Chest drain safety documentation', 'SURGICAL', 'cardiothoracic', 'DATA_VALIDATION', 'MEDIUM', 'Chest drain safety documentation', 'Chest drain inserted AND any of: side/site not recorded, post-insertion radiograph absent, underwater-seal check absent, or output charting not started', 'Block procedure-record completion until side, site, technique, post-insertion film and initial output/swing status are documented; schedule output charting; surface the ''never clamp a bubbling drain'' advisory on the observation chart', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_06', 'Pleural and pericardial fluid must be sent for TB studies', 'SURGICAL', 'cardiothoracic', 'DATA_VALIDATION', 'MEDIUM', 'Pleural and pericardial fluid must be sent for TB studies', 'Empyema drainage, effusion aspiration or pericardial window recorded AND no TB microscopy/culture (or Xpert) request linked to the specimen', 'Prompt the ordering of TB studies plus cytology/culture on every pleural and pericardial specimen — tuberculosis is a leading local cause and a missed send loses the diagnostic window; link results to the national TB programme workflow when positive', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_07', 'Prophylactic antibiotics for tube thoracostomy in chest trauma', 'SURGICAL', 'cardiothoracic', 'THERAPY', 'MEDIUM', 'Prophylactic antibiotics for tube thoracostomy in chest trauma', 'Chest drain placed for traumatic haemothorax/pneumothorax AND no peri-procedural antibiotic recorded', 'Prompt a first-generation cephalosporin (or local-policy agent) at insertion per trauma convention, and tetanus review for penetrating wounds; continue only per protocol — prolonged courses are not indicated for the drain alone', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_08', 'Anti-TB therapy linkage for tuberculous pericardial/pleural disease', 'SURGICAL', 'cardiothoracic', 'THERAPY', 'MEDIUM', 'Anti-TB therapy linkage for tuberculous pericardial/pleural disease', 'TB confirmed or clinically probable on pericardial or pleural specimens AND no anti-TB regimen active on the medication record', 'Raise a start-treatment task routed to the TB programme pathway (with steroid adjunct consideration for pericarditis per national guideline); surgery drains the space, chemotherapy treats the disease — both must be on the record', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_09', 'Chest drain daily review and removal criteria', 'SURGICAL', 'cardiothoracic', 'MONITORING', 'MEDIUM', 'Chest drain daily review and removal criteria', 'Chest drain in situ: daily check of output volume/character, swing, bubbling and dressing; removal criteria = no air leak, output below the unit threshold (~100-200 ml/24 h serous), lung expanded on imaging', 'Schedule daily drain review tasks; when criteria met, prompt removal with breath-hold occlusive technique and a post-removal radiograph; flag any drain in situ beyond 7 days without an escalation note to the surgical team', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CTS_10', 'Post-thoracic-surgery clinic and physiology review', 'SURGICAL', 'cardiothoracic', 'FOLLOW_UP', 'MEDIUM', 'Post-thoracic-surgery clinic and physiology review', 'Thoracotomy, decortication, pericardial window or PDA ligation completed AND no follow-up encounter booked at discharge', 'Auto-book: wound and radiograph review at 2 weeks, functional review at 6 weeks (echo for pericardial/cardiac cases, spirometry consideration post-decortication); TB cases additionally linked to programme review dates; flag non-attendance to community follow-up', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/cardiothoracic-rules.jsonl","rule_key":"SURG-CTS-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_01', 'Stoma site marking before resection with possible stoma', 'SURGICAL', 'colorectal', 'DATA_VALIDATION', 'MEDIUM', 'Stoma site marking before resection with possible stoma', 'If a colorectal resection is booked where a stoma is planned or reasonably possible (Hartmann''s, low anterior resection, emergency colectomy), and no preoperative stoma site marking is documented, the booking is incomplete.', 'Flag the theatre booking; prompt stoma-site marking and counselling by the most stoma-experienced available clinician; allow documented override only for immediate life-threat emergencies.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_02', 'Histology and staging before elective cancer resection', 'SURGICAL', 'colorectal', 'DATA_VALIDATION', 'MEDIUM', 'Histology and staging before elective cancer resection', 'If an elective colorectal cancer resection is booked without recorded tissue diagnosis and staging imaging (CT chest-abdomen-pelvis or best available equivalent), the case does not meet MDT-readiness criteria.', 'Block elective listing until histology and staging records are attached, or a senior surgeon documents why the case must proceed without them (e.g. obstructing tumour treated as urgent).', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_03', 'Rectal cancer mandates MDT before resection', 'SURGICAL', 'colorectal', 'CLASSIFICATION', 'MEDIUM', 'Rectal cancer mandates MDT before resection', 'If a confirmed or suspected rectal adenocarcinoma is on a surgical pathway and no multidisciplinary team decision is recorded, the case is classified as MDT-pending and must not proceed to resection, because neoadjuvant therapy may change the operation or avoid it.', 'Route the case to the central hospital colorectal MDT worklist; hold elective resection booking until an MDT outcome is recorded; emergency obstruction may be defunctioned with a stoma without waiting for MDT.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_04', 'Anastomotic leak pattern after colorectal anastomosis', 'SURGICAL', 'colorectal', 'DANGER_SIGN', 'HIGH', 'Anastomotic leak pattern after colorectal anastomosis', 'If a patient between postoperative day 2 and day 7 of a colorectal anastomosis develops sustained tachycardia above 100, new atrial fibrillation, fever, rising inflammatory markers, increasing abdominal pain, or faeculent/purulent drain output, anastomotic leak is the presumed diagnosis until excluded.', 'Raise a danger-sign alert; senior surgical review within 1 hour; recommend contrast CT where available or return to theatre on clinical grounds where imaging is not accessible; do not start anticoagulation for new atrial fibrillation without considering leak as the driver.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_05', 'Failed or bloody volvulus decompression is gangrene until proven otherwise', 'SURGICAL', 'colorectal', 'DANGER_SIGN', 'HIGH', 'Failed or bloody volvulus decompression is gangrene until proven otherwise', 'If endoscopic detorsion of sigmoid volvulus fails, returns blood or dark mucosa, or the patient has peritonism or systemic toxicity, gangrenous bowel is presumed.', 'Escalate to EMERGENCY laparotomy pathway immediately; do not repeat decompression attempts or observe overnight.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_06', 'Colorectal antibiotic prophylaxis covers anaerobes', 'SURGICAL', 'colorectal', 'THERAPY', 'MEDIUM', 'Colorectal antibiotic prophylaxis covers anaerobes', 'If any colorectal procedure opening or resecting large bowel is booked, prophylaxis must cover both aerobic gram-negative organisms and anaerobes: intravenous cefazolin (or ceftriaxone per local policy) plus metronidazole within 60 minutes before incision, with intra-operative redosing for prolonged cases per agent half-life.', 'Prompt combination prophylaxis at induction with timing capture; alert if metronidazole is missing from a colorectal booking''s prophylaxis plan; convert to treatment course when established peritonitis is coded.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_07', 'New stoma viability and output surveillance', 'SURGICAL', 'colorectal', 'MONITORING', 'MEDIUM', 'New stoma viability and output surveillance', 'If a new stoma is formed, stoma colour, spout, and output must be recorded at least once per nursing shift for the first 48 hours; a dusky or black stoma, no output beyond 24–48 hours with distension, or high output above 1500 ml/day each require escalation.', 'Generate per-shift stoma observation tasks for 48 hours then daily; alert the surgical team on dusky/black colour (possible ischaemia), absent output with distension (possible obstruction), or sustained high output (fluid and electrolyte replacement plan needed).', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_08', 'Post-resection colorectal cancer surveillance', 'SURGICAL', 'colorectal', 'FOLLOW_UP', 'MEDIUM', 'Post-resection colorectal cancer surveillance', 'If a patient has completed curative colorectal cancer resection, surveillance follows: clinical review with CEA where available every 6 months for 3 years then annually to 5 years; colonoscopy at 1 year post-resection (or completion colonoscopy within 6 months if the colon was obstructed and not fully evaluated preoperatively), then per findings; imaging per MDT plan.', 'Auto-generate the surveillance schedule at histology sign-off; book the 1-year (or 6-month completion) colonoscopy; flag missed surveillance events to the responsible clinic.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_CR_09', 'Perianal abscess needs a fistula check', 'SURGICAL', 'colorectal', 'FOLLOW_UP', 'MEDIUM', 'Perianal abscess needs a fistula check', 'If a perianal abscess was drained, a dedicated review at about 6 weeks is required to detect fistula-in-ano, which develops in a large minority; persistent discharge at review indicates a track.', 'Auto-book the 6-week review at drainage; if discharge or recurrent sepsis is recorded, route to EUA listing; prompt diabetes screening and HIV test offer at the same review if not already recorded.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/colorectal-rules.jsonl","rule_key":"SURG-CR-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_01', 'Post-tonsillectomy haemorrhage', 'SURGICAL', 'ent', 'DANGER_SIGN', 'HIGH', 'Post-tonsillectomy haemorrhage', 'Any fresh bleeding from mouth or nose, repeated swallowing in a sleeping child, or vomited blood within 14 days of tonsillectomy/adenoidectomy — even if it has apparently stopped', 'Treat as an emergency: admit, IV access and group-and-save, keep nil by mouth, senior ENT/surgical review; a ''herald bleed'' that stopped still mandates observation because it may precede major haemorrhage; theatre for arrest of bleeding if any ongoing loss', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_02', 'Stridor or impending airway obstruction', 'SURGICAL', 'ent', 'DANGER_SIGN', 'HIGH', 'Stridor or impending airway obstruction', 'Stridor at rest, drooling, tripod posture, rising respiratory rate with falling conscious level, or oxygen desaturation in a patient with neck swelling, deep neck infection, airway foreign body or post-thyroid/neck surgery haematoma', 'Critical alert: do not lie the patient flat, do not attempt blind instrumentation; summon the most senior airway-capable clinicians; for post-operative neck haematoma open the wound at the bedside to release the clot; prepare surgical airway kit in parallel with intubation attempts', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_03', 'Tracheostomy tube blockage or displacement', 'SURGICAL', 'ent', 'DANGER_SIGN', 'HIGH', 'Tracheostomy tube blockage or displacement', 'Tracheostomised patient with sudden respiratory distress, inability to pass a suction catheter, loss of airflow at the tube, or surgical emphysema', 'Follow the bedside emergency algorithm: remove inner cannula, suction, deflate cuff, remove the tube if obstruction persists (fresh stoma: use stay sutures/dilators), oxygenate face AND stoma; every ward accepting a tracheostomy must display the algorithm and stock a spare tube, one size smaller, and dilators at the bed', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_04', 'Tonsillitis episode-frequency criteria check', 'SURGICAL', 'ent', 'CLASSIFICATION', 'MEDIUM', 'Tonsillitis episode-frequency criteria check', 'Tonsillectomy booked for recurrent tonsillitis AND documented episode history does not reach approximately 7 episodes in 1 year, 5 per year over 2 years, or 3 per year over 3 years', 'Prompt the surgeon to record either the qualifying documented episode count or an explicit alternative indication (obstruction, quinsy recurrence, suspected neoplasm, febrile convulsions with tonsillitis); listing proceeds with the justification captured', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_05', 'Pre-mastoidectomy hearing and facial nerve baseline', 'SURGICAL', 'ent', 'DATA_VALIDATION', 'MEDIUM', 'Pre-mastoidectomy hearing and facial nerve baseline', 'Mastoidectomy or middle-ear surgery booked AND (no pre-operative hearing assessment recorded OR no pre-operative facial nerve status recorded)', 'Block theatre listing until baseline audiometry (or documented reason none was obtainable, with tuning-fork findings) and facial nerve function are on the record — both are medicolegal baselines for recognised complications', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_06', 'Antibiotic prophylaxis for clean-contaminated head and neck surgery', 'SURGICAL', 'ent', 'THERAPY', 'MEDIUM', 'Antibiotic prophylaxis for clean-contaminated head and neck surgery', 'Procedure entering the upper aerodigestive mucosa (tonsillectomy excluded per local policy, but including deep neck drainage, mastoid, laryngeal and tracheostomy surgery) AND no prophylactic antibiotic recorded before incision', 'Prompt for a prophylactic agent with streptococcal and anaerobic cover per local formulary at induction; for established abscesses continue therapeutic (not just prophylactic) antibiotics and adjust to culture', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_07', 'First-72-hour tracheostomy observations', 'SURGICAL', 'ent', 'MONITORING', 'MEDIUM', 'First-72-hour tracheostomy observations', 'New tracheostomy formed within the previous 72 hours', 'Schedule hourly airway checks initially (tube patency, secretions, cuff pressure once per shift, stoma site, surgical emphysema), continuous pulse oximetry, humidification; verify bedside safety equipment each shift and record the check', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_08', 'Overnight observation after adenotonsillectomy for obstructive symptoms', 'SURGICAL', 'ent', 'MONITORING', 'MEDIUM', 'Overnight observation after adenotonsillectomy for obstructive symptoms', 'Adenotonsillectomy performed for obstructive sleep-disordered breathing OR child under 3 years OR severe obstructive symptoms documented pre-operatively', 'Do not day-case: schedule overnight admission with pulse oximetry, given the elevated risk of post-obstructive airway events on the first night', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_09', 'Mastoid cavity lifelong surveillance', 'SURGICAL', 'ent', 'FOLLOW_UP', 'MEDIUM', 'Mastoid cavity lifelong surveillance', 'Canal-wall-down mastoidectomy recorded AND no future cavity-care appointment exists at discharge', 'Auto-book pack removal at 2-3 weeks and recurring (at least annual) cavity inspection/microsuction; flag defaulters — an unattended cavity accumulates debris and infection, and recurrent cholesteatoma must be excluded', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ENT_10', 'Post-bronchoscopy review after airway foreign body', 'SURGICAL', 'ent', 'FOLLOW_UP', 'MEDIUM', 'Post-bronchoscopy review after airway foreign body', 'Rigid bronchoscopy for foreign body completed, especially for vegetable matter or delayed presentation', 'Review within 48 hours for fever or respiratory symptoms and again at 2 weeks; arrange chest radiograph if symptomatic — retained fragments and post-obstructive pneumonia are the key late risks', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/ent-rules.jsonl","rule_key":"SURG-ENT-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_01', 'WHO checklist gates knife-to-skin', 'SURGICAL', 'general_surgery', 'DATA_VALIDATION', 'MEDIUM', 'WHO checklist gates knife-to-skin', 'If an operative record is being opened for any procedure and the WHO Surgical Safety Checklist sign-in and time-out are not recorded as complete, the operative note must not proceed to the incision step.', 'Block progression of the operative record past positioning until checklist sign-in and time-out are captured; prompt the recording clinician to complete them with the theatre team.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_02', 'Group-and-save before laparotomy', 'SURGICAL', 'general_surgery', 'DATA_VALIDATION', 'MEDIUM', 'Group-and-save before laparotomy', 'If an emergency laparotomy is booked and no group-and-save or cross-match sample is recorded within the current admission, the booking is incomplete.', 'Flag the theatre booking as incomplete and prompt for blood bank sample; allow documented override by the operating surgeon for immediate life-threat cases.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_03', 'Post-laparotomy intra-abdominal sepsis pattern', 'SURGICAL', 'general_surgery', 'DANGER_SIGN', 'HIGH', 'Post-laparotomy intra-abdominal sepsis pattern', 'If a patient between postoperative day 1 and day 7 of an abdominal operation has sustained heart rate above 100, new or worsening abdominal pain, fever, or rising early-warning score, intra-abdominal sepsis (leak, collection, ischaemia) is the presumed cause until excluded.', 'Raise a danger-sign alert to the surgical team for senior review within 1 hour; recommend septic screen and senior decision on imaging versus return to theatre; do not attribute deterioration to pain or chest infection without senior assessment.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_04', 'Irreducible hernia with pain is strangulation until proven otherwise', 'SURGICAL', 'general_surgery', 'DANGER_SIGN', 'HIGH', 'Irreducible hernia with pain is strangulation until proven otherwise', 'If a documented hernia becomes irreducible and painful, or shows overlying skin changes, or is accompanied by vomiting or obstruction, strangulation must be presumed.', 'Escalate to EMERGENCY pathway: analgesia, intravenous fluids, nasogastric tube if obstructed, and immediate surgical referral; do not schedule for an elective list.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_05', 'High-risk patient triggers pre-operative escalation', 'SURGICAL', 'general_surgery', 'CLASSIFICATION', 'MEDIUM', 'High-risk patient triggers pre-operative escalation', 'If a patient listed for intermediate or major surgery is ASA III or above, or has predicted major blood loss, or is over 65 with an emergency abdominal indication, they are classified high perioperative risk.', 'Require documented anaesthetic review before theatre, ensure blood availability, and prompt consideration of transfer to or booking at a central hospital with HDU capacity.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_06', 'Antibiotic prophylaxis for abdominal surgery', 'SURGICAL', 'general_surgery', 'THERAPY', 'MEDIUM', 'Antibiotic prophylaxis for abdominal surgery', 'If a clean-contaminated or contaminated abdominal procedure is booked, single-dose intravenous cefazolin should be given within 60 minutes before incision, with metronidazole added whenever the gastrointestinal lumen will or may be opened; established infection converts prophylaxis to a treatment course.', 'Prompt prophylaxis agent and timing at anaesthetic induction; record administration time in the operative record; suppress the prompt when a treatment course is already charted.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_07', 'Structured post-operative observation frequency', 'SURGICAL', 'general_surgery', 'MONITORING', 'MEDIUM', 'Structured post-operative observation frequency', 'If a patient returns from any general surgical procedure under general or spinal anaesthesia, observations (vital signs and early-warning score) are due at least hourly for the first 4 hours, then 4-hourly for 24 hours, with any score breach escalated per the early-warning protocol.', 'Generate the post-operative observation schedule on the ward task list and alert the responsible nurse when an observation is overdue or the score breaches threshold.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_08', 'Conservative small bowel obstruction trial has a clock', 'SURGICAL', 'general_surgery', 'MONITORING', 'MEDIUM', 'Conservative small bowel obstruction trial has a clock', 'If adhesive small bowel obstruction is managed conservatively, nasogastric output, abdominal signs, and fluid balance must be reviewed at least 12-hourly, and failure to resolve by 48–72 hours mandates senior surgical review for operative decision.', 'Start a 72-hour review timer at diagnosis; surface 12-hourly review tasks; at 48 hours flag the case for mandatory senior surgical decision and record the decision outcome.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_GS_09', 'Post-operative wound and histology review', 'SURGICAL', 'general_surgery', 'FOLLOW_UP', 'MEDIUM', 'Post-operative wound and histology review', 'If a patient is discharged after a general surgical procedure, a wound review at 7–14 days at the nearest facility is due, and any specimen sent to histology requires a documented result review and patient communication within 4 weeks.', 'Auto-book wound review follow-up on discharge; open a histology-tracking task that stays red until the result is reviewed, actioned, and communicated to the patient.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/general_surgery-rules.jsonl","rule_key":"SURG-GS-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_MAXF_01', 'Ludwig angina / airway-threatening floor-of-mouth swelling', 'SURGICAL', 'maxillofacial', 'DANGER_SIGN', 'HIGH', 'Ludwig angina / airway-threatening floor-of-mouth swelling', 'Bilateral submandibular swelling with raised/woody floor of mouth, protruding or elevated tongue, drooling, voice change, or difficulty lying flat — usually with a dental source', 'Critical alert: airway team summoned before any other action; nurse sitting up, do not sedate; theatre planned with awake-intubation/surgical-airway capability; decompression and dental source removal follow airway control — antibiotics alone are not a plan', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/maxillofacial-rules.jsonl","rule_key":"SURG-MAXF-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_MAXF_02', 'Retrobulbar haemorrhage after facial fracture or its reduction', 'SURGICAL', 'maxillofacial', 'DANGER_SIGN', 'HIGH', 'Retrobulbar haemorrhage after facial fracture or its reduction', 'Increasing orbital pain, proptosis, falling visual acuity, or fixed dilated pupil in the hours after zygomatic/orbital fracture or its surgical reduction', 'Sight is lost in under an hour: immediate senior call and lateral canthotomy/cantholysis pathway; do not send for imaging first; this is why hourly eye observations are scheduled after zygoma surgery', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/maxillofacial-rules.jsonl","rule_key":"SURG-MAXF-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_MAXF_03', 'Airway risk in the maxillomandibular-fixed patient', 'SURGICAL', 'maxillofacial', 'DANGER_SIGN', 'HIGH', 'Airway risk in the maxillomandibular-fixed patient', 'Patient in wire MMF with vomiting, respiratory distress, falling saturations or reduced conscious level', 'Cut the INTERMAXILLARY wires immediately with the bedside wire cutters (not the arch bars), suction, and position for airway safety; every MMF patient carries wire cutters and every receiving ward is briefed — absence of cutters at the bedside is a reportable safety defect', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/maxillofacial-rules.jsonl","rule_key":"SURG-MAXF-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_MAXF_04', 'Le Fort level assignment for midface fractures', 'SURGICAL', 'maxillofacial', 'CLASSIFICATION', 'MEDIUM', 'Le Fort level assignment for midface fractures', 'Midface fracture recorded without a Le Fort level (I palate-mobile, II pyramidal with nasofrontal involvement, III craniofacial disjunction) or an explicit ''not classifiable/comminuted'' note', 'Prompt level assignment from mobility examination and imaging; level II/III triggers CSF-leak assessment and neurosurgical/base-of-skull consultation before fixation planning', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/maxillofacial-rules.jsonl","rule_key":"SURG-MAXF-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
