('SURG_ORTH_01', 'Suspected acute compartment syndrome', 'SURGICAL', 'orthopaedics', 'DANGER_SIGN', 'HIGH', 'Suspected acute compartment syndrome', 'Limb injury or tight cast AND (pain out of proportion to injury OR pain on passive stretch of compartment muscles OR progressive paraesthesia OR tense swollen compartment) — pulses may still be present', 'Raise critical alert; split all circumferential casts/dressings to skin immediately; keep limb at heart level; senior surgical review now with emergency fasciotomy as the default outcome; do not delay for pressure measurement or imaging', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_02', 'Pulseless limb after fracture or dislocation', 'SURGICAL', 'orthopaedics', 'DANGER_SIGN', 'HIGH', 'Pulseless limb after fracture or dislocation', 'Absent distal pulse or capillary refill over 3 seconds distal to a fracture/dislocation, before or after reduction', 'Emergency pathway: reduce/realign and reassess immediately; if perfusion not restored, escalate for surgical exploration or vascular referral within the ischaemia window; document times of injury, reduction and reassessment', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_03', 'Gustilo-Anderson grading required for open fractures', 'SURGICAL', 'orthopaedics', 'CLASSIFICATION', 'MEDIUM', 'Gustilo-Anderson grading required for open fractures', 'Any fracture recorded with an overlying wound or marked ''open'' AND no Gustilo-Anderson grade captured after the first debridement', 'Prompt the operating surgeon to assign Gustilo-Anderson grade (I, II, IIIA, IIIB, IIIC) intra-operatively — grading in casualty is provisional only; grade IIIB/IIIC triggers referral-level soft-tissue/vascular pathway', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_04', 'Open fracture bundle completeness', 'SURGICAL', 'orthopaedics', 'DATA_VALIDATION', 'MEDIUM', 'Open fracture bundle completeness', 'Open fracture recorded AND any of: tetanus prophylaxis status missing, first IV antibiotic time missing, injury time missing', 'Block completion of the open-fracture record until tetanus status, antibiotic administration time and injury time are documented; flag antibiotic delay beyond 1 hour from arrival', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_05', 'Surgical antibiotic prophylaxis for implant surgery', 'SURGICAL', 'orthopaedics', 'THERAPY', 'MEDIUM', 'Surgical antibiotic prophylaxis for implant surgery', 'Booked procedure involves an implant (nail, plate, arthroplasty, wires) AND no prophylactic antibiotic recorded within 60 minutes before incision', 'Prompt anaesthetic/surgical team to give a first-generation cephalosporin (or per local policy where allergy documented) at induction, within 60 minutes before incision; record agent and time on the operative record', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_06', 'VTE prophylaxis after hip fracture surgery', 'SURGICAL', 'orthopaedics', 'THERAPY', 'MEDIUM', 'VTE prophylaxis after hip fracture surgery', 'Patient over 40 with hip fracture or arthroplasty AND no VTE prophylaxis (pharmacological or mechanical) recorded within 24 hours post-operatively AND no contraindication documented', 'Prompt prescriber to start low-molecular-weight heparin per local protocol or, where unavailable/contraindicated, document mechanical prophylaxis and early mobilisation as the plan', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_07', 'Neurovascular observations after limb surgery or casting', 'SURGICAL', 'orthopaedics', 'MONITORING', 'MEDIUM', 'Neurovascular observations after limb surgery or casting', 'Limb surgery, manipulation or new circumferential cast completed within the last 24 hours', 'Schedule neurovascular observations (pain score, passive stretch pain, colour, warmth, capillary refill, sensation, movement, distal pulses) hourly for 4 hours then 4-hourly for 24 hours; any deterioration routes to the compartment-syndrome danger sign', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_08', 'Fracture clinic radiographic review', 'SURGICAL', 'orthopaedics', 'FOLLOW_UP', 'MEDIUM', 'Fracture clinic radiographic review', 'Operatively or conservatively managed long-bone fracture discharged without a booked fracture-clinic appointment', 'Auto-propose follow-up: wound/cast check at 2 weeks, radiograph at 6 weeks, and union assessment at 3 months; paediatric supracondylar wires booked for removal at 3-4 weeks; flag non-attendance for community follow-up', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_ORTH_09', 'Clubfoot brace compliance surveillance', 'SURGICAL', 'orthopaedics', 'FOLLOW_UP', 'MEDIUM', 'Clubfoot brace compliance surveillance', 'Ponseti tenotomy recorded AND child under 5 years AND no foot-abduction-brace review in the past 3 months', 'Generate community/clinic recall — bracing lapses are the leading cause of relapse; record brace condition and hours of wear at each visit', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/orthopaedics-rules.jsonl","rule_key":"SURG-ORTH-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_01', 'Current weight is mandatory on every paediatric surgical episode', 'SURGICAL', 'paediatric_surgery', 'DATA_VALIDATION', 'MEDIUM', 'Current weight is mandatory on every paediatric surgical episode', 'If a surgical episode is opened for a patient under 12 years and no weight measured within the current presentation is recorded, drug dosing, fluid prescription, and anaesthesia cannot be safely calculated.', 'Make current measured weight a required field before theatre booking or any weight-based prescription; flag estimated weights explicitly as estimates.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_02', 'Electrolyte correction gates pyloromyotomy booking', 'SURGICAL', 'paediatric_surgery', 'DATA_VALIDATION', 'MEDIUM', 'Electrolyte correction gates pyloromyotomy booking', 'If pyloromyotomy is being booked and the most recent electrolytes do not document corrected hypochloraemic alkalosis (chloride and bicarbonate within the unit''s accepted pre-anaesthetic range), the infant is not theatre-ready — anaesthetising the uncorrected infant risks postoperative apnoea.', 'Block theatre listing until a post-resuscitation electrolyte result within range is attached; display the correction status on the booking; there is no emergency override — the surgical condition itself is never the emergency.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_03', 'Bilious vomiting in a neonate is malrotation until excluded', 'SURGICAL', 'paediatric_surgery', 'DANGER_SIGN', 'HIGH', 'Bilious vomiting in a neonate is malrotation until excluded', 'If green (bilious) vomiting is recorded in a neonate or young infant, midgut malrotation with volvulus is the presumed diagnosis; the midgut can infarct within hours.', 'Raise an emergency alert; nasogastric decompression, intravenous resuscitation, and immediate surgical referral; upper GI contrast only if the child is stable and it will not delay theatre or transfer; block any pathway that assigns this presentation to routine observation.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_04', 'Irreducible inguinal hernia in an infant', 'SURGICAL', 'paediatric_surgery', 'DANGER_SIGN', 'HIGH', 'Irreducible inguinal hernia in an infant', 'If a paediatric inguinal hernia is recorded as irreducible, tender, or associated with vomiting or a red overlying scrotum/groin, incarceration threatening bowel and testis is presumed.', 'Emergency surgical referral; allow one senior-supervised attempt at taxis with analgesia in the non-toxic child; failed reduction or toxicity routes straight to theatre; successful reduction still books repair on the same admission.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_05', 'Hirschsprung-associated enterocolitis pattern', 'SURGICAL', 'paediatric_surgery', 'DANGER_SIGN', 'HIGH', 'Hirschsprung-associated enterocolitis pattern', 'If a child with confirmed or suspected Hirschsprung disease develops abdominal distension with fever, lethargy, or foul explosive diarrhoea, Hirschsprung-associated enterocolitis is presumed — it is the leading killer in this disease.', 'Alert for emergency management: resuscitation, broad-spectrum antibiotics including anaerobic cover, rectal washouts (not enemas under pressure), and urgent surgical review for possible emergency stoma; escalate scheduling of any pending definitive surgery discussion.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_06', 'Anorectal malformation level drives the operative pathway', 'SURGICAL', 'paediatric_surgery', 'CLASSIFICATION', 'MEDIUM', 'Anorectal malformation level drives the operative pathway', 'If an anorectal malformation is recorded, classify by level within 24–48 hours of birth: visible perineal fistula with meconium classifies LOW (candidate for primary anoplasty under experienced assessment); no visible fistula, meconium in urine, or a flat perineum classifies HIGH (divided sigmoid colostomy now, staged PSARP later at specialist centre).', 'Present the level-classification checklist on the neonatal record; route HIGH classifications to emergency colostomy booking and specialist referral; attach the associated-anomaly (VACTERL) screening bundle to every classification.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_07', 'Weight-based single-dose prophylaxis for paediatric surgery', 'SURGICAL', 'paediatric_surgery', 'THERAPY', 'MEDIUM', 'Weight-based single-dose prophylaxis for paediatric surgery', 'If a paediatric surgical procedure is booked, prophylaxis is a single weight-calculated intravenous dose of cefazolin within 60 minutes before incision, adding metronidazole for any bowel-opening or contaminated procedure; clean minor day-cases may omit prophylaxis per unit policy; established peritonitis (typhoid perforation, gangrenous intussusception) uses a treatment course instead.', 'Prompt weight-calculated prophylaxis at induction using the recorded current weight; alert if the ordered dose does not match the weight-based calculation; suppress the prompt when a treatment course is charted.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_08', 'Paediatric postoperative physiology and fluid surveillance', 'SURGICAL', 'paediatric_surgery', 'MONITORING', 'MEDIUM', 'Paediatric postoperative physiology and fluid surveillance', 'If a child is postoperative from abdominal surgery, age-appropriate paediatric early-warning observations are due at least hourly for 4 hours then per protocol, with strict fluid balance (maintenance plus measured losses, glucose-containing fluids for neonates) and nasogastric/stoma output replacement; neonates additionally need temperature and glucose checks because cold and hypoglycaemia kill quietly.', 'Generate the age-banded observation and fluid-balance task schedule at ward return; alert on paediatric early-warning breaches, on any neonate temperature or glucose excursion, and on stoma/nasogastric outputs not reflected in the fluid prescription.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_09', 'Ex-premature infants need postoperative apnoea monitoring', 'SURGICAL', 'paediatric_surgery', 'MONITORING', 'MEDIUM', 'Ex-premature infants need postoperative apnoea monitoring', 'If an infant below the unit''s corrected-gestational-age threshold (commonly under about 60 weeks post-conceptional age) undergoes anaesthesia, day-case discharge is unsafe — postoperative apnoea risk mandates overnight saturation and apnoea monitoring.', 'At booking, compute corrected age from recorded gestation and birth date; block day-case pathway selection for infants under threshold and reserve a monitored bed instead.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PS_10', 'Orchidopexy outcome review at 6–12 months', 'SURGICAL', 'paediatric_surgery', 'FOLLOW_UP', 'MEDIUM', 'Orchidopexy outcome review at 6–12 months', 'If orchidopexy has been performed, a follow-up at 6–12 months documenting testicular position and size (atrophy check) is part of the operation''s outcome, alongside early wound review; adolescents are additionally taught self-examination.', 'Auto-book the early wound review and the 6–12 month position-and-size review at operation coding; flag operations with no outcome review recorded by 15 months; attach the adolescent self-examination education item to the record for later delivery.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/paediatric_surgery-rules.jsonl","rule_key":"SURG-PS-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_01', 'Necrotising soft-tissue infection recognition', 'SURGICAL', 'plastics', 'DANGER_SIGN', 'HIGH', 'Necrotising soft-tissue infection recognition', 'Soft-tissue infection with any of: pain out of proportion, oedema or tenderness extending beyond visible erythema, skin dusky/blistering/necrotic patches, crepitus, rapidly advancing edge, or systemic toxicity disproportionate to the visible wound', 'Critical alert: this is a surgical emergency, not an antibiotic titration problem — senior surgical review now, mark and time the advancing edge, resuscitate in parallel, theatre for radical debridement within hours; book the 12-24 h relook at the first operation', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_02', 'Circumferential deep burn threatening perfusion or ventilation', 'SURGICAL', 'plastics', 'DANGER_SIGN', 'HIGH', 'Circumferential deep burn threatening perfusion or ventilation', 'Circumferential full-thickness burn of a limb with progressive pain, tightness, reduced distal perfusion or sensation — or of the chest with rising ventilation pressures/restricted excursion', 'Bedside escharotomy pathway immediately (longitudinal releasing incisions through eschar along standard lines, chest grid for ventilation restriction); do not transfer an unreleased circumferential burn; reassess perfusion after release and document', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_03', 'Flap or replant vascular compromise', 'SURGICAL', 'plastics', 'DANGER_SIGN', 'HIGH', 'Flap or replant vascular compromise', 'Post-operative flap/replant that is pale/white (arterial) or congested/purple with brisk dark bleeding (venous), cool, or with lost capillary refill signal', 'Immediate surgeon notification — salvage is measured in hours; loosen dressings/sutures at the bedside per protocol, ensure warmth, elevate for congestion or level for pallor, and prepare for return to theatre; never book flap concerns to the next routine round', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_04', 'Burn extent and depth assessment standard', 'SURGICAL', 'plastics', 'CLASSIFICATION', 'MEDIUM', 'Burn extent and depth assessment standard', 'Burn recorded AND (%TBSA missing, or paediatric burn assessed without Lund-Browder, or depth not recorded) — erythema must be excluded from %TBSA', 'Require %TBSA (Lund-Browder chart for children, rule-of-nines acceptable for adults) and depth category at admission and at 48-72 h re-review (burns declare late); the %TBSA field drives fluid-resuscitation calculation and referral criteria', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_05', 'Burns referral-criteria screen', 'SURGICAL', 'plastics', 'DATA_VALIDATION', 'MEDIUM', 'Burns referral-criteria screen', 'Burn admission where any of: %TBSA over ~10% (adult) or ~5% (child), full-thickness component, involvement of face/hands/perineum/major joints, inhalational features, electrical or chemical mechanism, or extremes of age — and no burns-unit referral recorded', 'Surface the referral checklist and require either a referral record or a documented senior decision to manage locally; inhalational features additionally trigger early airway assessment', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_06', 'Tetanus and antimicrobial policy for contaminated soft-tissue wounds', 'SURGICAL', 'plastics', 'THERAPY', 'MEDIUM', 'Tetanus and antimicrobial policy for contaminated soft-tissue wounds', 'Burn, crush, bite or contaminated soft-tissue wound recorded AND tetanus prophylaxis status missing; systemic antibiotics recorded for a clean burn without infection signs', 'Require tetanus status on every such wound; conversely flag routine systemic antibiotic prophylaxis for burns (not indicated without infection or peri-operative context) — topical antimicrobials and excision policy are the infection strategy', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_07', 'Adjuvant plan mandatory for keloid excision', 'SURGICAL', 'plastics', 'THERAPY', 'MEDIUM', 'Adjuvant plan mandatory for keloid excision', 'Keloid excision listed AND no adjuvant therapy plan (serial intralesional corticosteroid schedule, pressure device, or radiotherapy referral) attached to the episode', 'Block listing until the adjuvant pathway and recurrence counselling are documented — excision alone recurs in the majority and often worse; auto-generate the post-excision steroid-injection appointment series', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_08', 'Graft and donor-site check schedule', 'SURGICAL', 'plastics', 'MONITORING', 'MEDIUM', 'Graft and donor-site check schedule', 'Split/full-thickness graft applied: first inspection due day 3-5 (earlier for soaking, odour, fever or pain spike); donor-site dressing retained 10-14 days', 'Schedule the day-3-5 graft take-down by trained staff with percentage-take recorded; unscheduled early take-down triggers infection review; haematoma/seroma found at inspection is evacuated and re-bolstered the same day; donor-site check booked at 10-14 days', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_09', 'Scar management and contracture surveillance after burns', 'SURGICAL', 'plastics', 'FOLLOW_UP', 'MEDIUM', 'Scar management and contracture surveillance after burns', 'Healed deep burn or grafted burn crossing a joint AND no scar-programme enrolment (pressure garments, silicone, physiotherapy, splintage) or joint-range review booked', 'Enrol in the scar-management programme at wound closure with reviews at 1, 3, 6 and 12 months recording joint range and photographs; children remain under surveillance through growth; falling range between visits generates a contracture-release assessment', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_PLAS_10', 'SCC margin chase and surveillance schedule', 'SURGICAL', 'plastics', 'FOLLOW_UP', 'MEDIUM', 'SCC margin chase and surveillance schedule', 'Skin-cancer excision performed AND (histology result not linked within 4 weeks OR involved margins without a re-excision/radiotherapy plan OR no surveillance appointments booked)', 'Task the team to chase and link histology; involved margins auto-generate a re-excision listing decision; book risk-based surveillance (typically 3-6 monthly for 2 years) with node-basin examination at each visit; persons with albinism additionally enrolled in whole-skin surveillance and sun-protection supply', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/plastics-rules.jsonl","rule_key":"SURG-PLAS-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_01', 'Every excised specimen has a histology request', 'SURGICAL', 'surgical_oncology', 'DATA_VALIDATION', 'MEDIUM', 'Every excised specimen has a histology request', 'If an operative record includes excision of any tissue (node, mass, ulcer edge, organ) and no histopathology request is attached, the operative record is incomplete — undiagnosed discarded tissue is an unrecoverable error.', 'Block operative-note finalisation until a histology request (with specimen orientation details where applicable) is linked, or an explicit senior-documented no-histology justification is recorded; open a results-tracking task automatically.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_02', 'Fresh-specimen and TB routing arranged before node biopsy', 'SURGICAL', 'surgical_oncology', 'DATA_VALIDATION', 'MEDIUM', 'Fresh-specimen and TB routing arranged before node biopsy', 'If an excisional lymph node biopsy is booked for suspected lymphoma, the laboratory pathway for a fresh (unfixed) specimen and for TB studies must be confirmed before induction — formalin destroys the immunophenotyping options and the node cannot be re-excised.', 'Add a specimen-routing confirmation checklist item to the booking; flag bookings without it; record in the operative note exactly which laboratory received which portion.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_03', 'Sarcoma-pattern mass classifies to biopsy-first, never shell-out', 'SURGICAL', 'surgical_oncology', 'CLASSIFICATION', 'MEDIUM', 'Sarcoma-pattern mass classifies to biopsy-first, never shell-out', 'If a soft tissue mass is recorded as over 5 cm, deep to fascia, rapidly enlarging, or recurrent after previous excision, classify as suspected sarcoma: the pathway is imaging then core/incisional biopsy then MDT-planned wide excision at central hospital — direct excision (shell-out) is a pathway violation that contaminates the field and worsens survival.', 'Route sarcoma-pattern masses to the biopsy-first worklist; warn when an excision is being booked against an unbiopsied mass matching these criteria and require senior override with reason; auto-refer confirmed sarcoma histology to central MDT.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_04', 'Changing chronic wound classifies to malignancy exclusion', 'SURGICAL', 'surgical_oncology', 'CLASSIFICATION', 'MEDIUM', 'Changing chronic wound classifies to malignancy exclusion', 'If a chronic wound, burn scar, or sinus is recorded with new changes — raised or everted edge, new nodularity, contact bleeding, or growth — classify to the Marjolin pathway: multi-quadrant edge biopsy before any further dressing-only plan.', 'Prompt edge biopsy ordering on matching wound-care records; flag wounds with documented change and no biopsy result within 4 weeks; route positive histology to EXPEDITED excision planning with reconstruction consult.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_05', 'Oncological compression emergencies', 'SURGICAL', 'surgical_oncology', 'DANGER_SIGN', 'HIGH', 'Oncological compression emergencies', 'If a patient on any cancer pathway develops new limb weakness or sphincter disturbance (spinal cord compression), stridor or facial/arm swelling (airway or superior vena cava obstruction), these are oncological emergencies where hours change outcome.', 'Raise an emergency alert; immediate senior review and same-day referral to the appropriate emergency pathway (steroids per policy and urgent radiotherapy/oncology contact for cord compression); do not schedule as routine oncology review.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_06', 'Early gastrostomy dislodgement is a surgical review', 'SURGICAL', 'surgical_oncology', 'DANGER_SIGN', 'HIGH', 'Early gastrostomy dislodgement is a surgical review', 'If a surgically placed feeding gastrostomy tube is recorded as dislodged within about 4 weeks of placement (immature tract), blind ward-level reinsertion risks intraperitoneal placement and peritonitis.', 'Alert that reinsertion must be by the surgical team (with contrast confirmation where available); block the routine tube-change task type for tubes younger than the maturity threshold; advise nil-by-tube and review if placement is in doubt.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_07', 'Proportionate prophylaxis for oncological surgery', 'SURGICAL', 'surgical_oncology', 'THERAPY', 'MEDIUM', 'Proportionate prophylaxis for oncological surgery', 'If an oncological procedure is booked, prophylaxis follows the wound class: single-dose cefazolin within 60 minutes before incision for clean cases with grafts, flaps, drains, or implants; add metronidazole where a gut lumen is opened (gastrostomy, colostomy); malnourished and immunosuppressed patients do not need prolonged prophylaxis — they need correctly timed single-dose prophylaxis plus nutritional attention.', 'Prompt wound-class-matched prophylaxis at induction with timing capture; flag postoperative continuation of prophylactic antibiotics beyond 24 hours as non-indicated.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_08', 'Flap, graft and reconstruction surveillance', 'SURGICAL', 'surgical_oncology', 'MONITORING', 'MEDIUM', 'Flap, graft and reconstruction surveillance', 'If a flap or skin graft was used to close an oncological excision, viability observation (colour, capillary refill, congestion for flaps; bolster integrity for grafts) is due per protocol in the first 48–72 hours, because a failing flap salvaged early is a different outcome from one found at first dressing change.', 'Generate flap-observation tasks at the unit''s protocol frequency for 72 hours; alert the surgical team on any recorded congestion, pallor, or bolster disruption; schedule first graft inspection at the protocol interval.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_09', 'Histology results tracked to an actioned decision', 'SURGICAL', 'surgical_oncology', 'MONITORING', 'MEDIUM', 'Histology results tracked to an actioned decision', 'If an oncological specimen has been sent, the loop closes only when the result is reviewed, an MDT or senior decision is recorded, and the patient is informed — commonly within 4 weeks; margin-positive excisions specifically require a documented re-excision decision.', 'Keep the results-tracking task red until result-reviewed, decision-recorded, and patient-informed are all captured; escalate results older than 4 weeks without action to the responsible consultant; auto-flag margin-positive reports for a re-excision decision field.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_SO_10', 'Structured surveillance after curative oncological excision', 'SURGICAL', 'surgical_oncology', 'FOLLOW_UP', 'MEDIUM', 'Structured surveillance after curative oncological excision', 'If a curative-intent excision is completed (sarcoma, melanoma, Marjolin SCC), a structured surveillance schedule per MDT is part of the treatment: commonly 3-monthly clinical review of the site and node basins in the first 2 years with chest imaging for sarcoma per protocol, then extending intervals; patients taught site and skin self-examination.', 'Auto-generate the MDT-specified surveillance schedule at histology sign-off; flag lapsed surveillance visits to the responsible clinic; attach self-examination education to the discharge record.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/surgical_oncology-rules.jsonl","rule_key":"SURG-SO-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_01', 'Coagulation and vitamin K before surgery in obstructive jaundice', 'SURGICAL', 'upper_gi_hpb', 'DATA_VALIDATION', 'MEDIUM', 'Coagulation and vitamin K before surgery in obstructive jaundice', 'If a patient with obstructive jaundice is booked for any operative or drainage procedure and no coagulation profile (or documented vitamin K administration) is recorded in the current episode, the booking is incomplete — obstructed biliary drainage impairs vitamin-K-dependent clotting.', 'Flag the booking; prompt coagulation testing and preoperative vitamin K; require documented senior override for emergencies that cannot wait.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_02', 'Tissue diagnosis attached to every gastric bypass or resection', 'SURGICAL', 'upper_gi_hpb', 'DATA_VALIDATION', 'MEDIUM', 'Tissue diagnosis attached to every gastric bypass or resection', 'If a gastrojejunostomy or gastric resection is being recorded and no biopsy of the obstructing or resected lesion is captured (preoperative endoscopic or intraoperative), the operative record is incomplete — benign-appearing outlet obstruction may be malignant.', 'Require a biopsy entry (or explicit documented reason for its absence) before the operative note can be finalised; open a histology-tracking task automatically.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_03', 'Cholangitis triad triggers the biliary sepsis pathway', 'SURGICAL', 'upper_gi_hpb', 'CLASSIFICATION', 'MEDIUM', 'Cholangitis triad triggers the biliary sepsis pathway', 'If a patient presents with fever or rigors plus jaundice plus right upper quadrant pain (Charcot pattern), classify as acute cholangitis; adding hypotension or confusion classifies severe cholangitis.', 'Route to the biliary sepsis pathway: blood cultures, intravenous antibiotics covering biliary flora, and urgent biliary decompression planning (ERCP where available, otherwise surgical); severe cholangitis escalates to EMERGENCY decompression and highest-acuity bed.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_04', 'Suspected cystic neoplasm exits the pseudocyst pathway', 'SURGICAL', 'upper_gi_hpb', 'CLASSIFICATION', 'MEDIUM', 'Suspected cystic neoplasm exits the pseudocyst pathway', 'If a pancreatic cystic lesion has no antecedent pancreatitis history, or shows septations, mural nodules, or solid components on imaging, it must not be classified as a pseudocyst.', 'Reclassify as indeterminate cystic lesion; block simple internal-drainage listing; route to central hospital MDT for neoplasm work-up.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_05', 'Bilious drain output after gastric or biliary surgery', 'SURGICAL', 'upper_gi_hpb', 'DANGER_SIGN', 'HIGH', 'Bilious drain output after gastric or biliary surgery', 'If drain output after gastrectomy, cholecystectomy, or bile duct surgery becomes bilious, or the patient develops fever, tachycardia, or peritonism in the first postoperative week, a duodenal stump leak or bile leak is presumed until excluded.', 'Raise a danger-sign alert; senior surgical review within 1 hour; nil by mouth and fluid resuscitation; senior decision on imaging, drainage, or return to theatre — do not simply observe a bilious drain.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_06', 'Fever after splenectomy is never trivial', 'SURGICAL', 'upper_gi_hpb', 'DANGER_SIGN', 'HIGH', 'Fever after splenectomy is never trivial', 'If a post-splenectomy patient (any interval since surgery, lifelong) presents with fever, overwhelming post-splenectomy infection must be presumed; in malaria-endemic settings severe malaria is a parallel presumption.', 'Alert the clinician to treat as sepsis immediately: cultures, empirical broad-spectrum antibiotics without waiting for results, and malaria testing; flag splenectomy status prominently on the patient banner.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_07', 'Biliary and upper GI prophylaxis targets enteric and biliary flora', 'SURGICAL', 'upper_gi_hpb', 'THERAPY', 'MEDIUM', 'Biliary and upper GI prophylaxis targets enteric and biliary flora', 'If a biliary, gastric, or pancreatic procedure is booked, give intravenous cefazolin (or ceftriaxone per local policy for high-risk biliary cases) within 60 minutes before incision, adding metronidazole where the gut lumen will be opened; established cholangitis or perforation converts prophylaxis to a treatment course.', 'Prompt agent, timing, and lumen-opening question at induction; record administration time; suppress prophylaxis prompt when a treatment course is charted.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_08', 'Splenectomy vaccination and education bundle', 'SURGICAL', 'upper_gi_hpb', 'THERAPY', 'MEDIUM', 'Splenectomy vaccination and education bundle', 'If a splenectomy is planned electively, vaccination against pneumococcus, meningococcus, and Haemophilus influenzae type b is due at least 2 weeks before surgery; if splenectomy was emergent, the same vaccines are due before discharge, together with documented lifelong infection-risk education.', 'Auto-generate the vaccination task at listing (elective) or at operation coding (emergency); block discharge summary sign-off until vaccination status and education are recorded or explicitly deferred with a follow-up booking.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_09', 'Drain surveillance after HPB and gastric surgery', 'SURGICAL', 'upper_gi_hpb', 'MONITORING', 'MEDIUM', 'Drain surveillance after HPB and gastric surgery', 'If a drain is in place after hepatobiliary, pancreatic, or gastric surgery, record volume and character at least daily; bilious, amylase-rich, or feculent change, or abrupt high volume, requires same-day surgical review; drains should have a documented removal plan by day 5.', 'Generate daily drain-charting tasks with character classification; alert the team on any concerning character change; flag any drain without a removal decision by postoperative day 5.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_UGI_10', 'Post-gastrectomy long-term follow-up obligations', 'SURGICAL', 'upper_gi_hpb', 'FOLLOW_UP', 'MEDIUM', 'Post-gastrectomy long-term follow-up obligations', 'If a patient has undergone partial or total gastrectomy, they require: histology-driven oncology MDT review within 4 weeks; lifelong vitamin B12 replacement (all total, and monitored after distal gastrectomy); iron and nutritional surveillance annually; and early re-referral for recurrent dysphagia, weight loss, or anaemia.', 'Auto-generate the B12 replacement recurring task and annual nutritional review at discharge coding; route histology to MDT; provide red-flag re-referral criteria on the discharge summary.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/upper_gi_hpb-rules.jsonl","rule_key":"SURG-UGI-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_01', 'Urine culture status before elective urological instrumentation', 'SURGICAL', 'urology', 'DATA_VALIDATION', 'MEDIUM', 'Urine culture status before elective urological instrumentation', 'If an elective procedure instrumenting the urinary tract (prostatectomy, cystolithotomy, urethrotomy, TURBT, stent change) is booked without a recorded urine culture result or a documented treated-bacteriuria course, the booking is incomplete — instrumenting infected urine seeds sepsis.', 'Flag the booking; prompt urine culture and, if positive, a completed treatment course before listing; emergencies bypass with culture taken at catheterisation and treatment running.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_02', 'Pain-onset time is a required field for acute scrotum', 'SURGICAL', 'urology', 'DATA_VALIDATION', 'MEDIUM', 'Pain-onset time is a required field for acute scrotum', 'If an acute scrotal presentation is being recorded, time of pain onset must be captured — it drives the torsion salvage window and every downstream decision.', 'Make pain-onset time mandatory on the acute scrotum form; auto-display elapsed time on the referral and theatre booking.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_03', 'Acute scrotum is torsion until proven otherwise', 'SURGICAL', 'urology', 'DANGER_SIGN', 'HIGH', 'Acute scrotum is torsion until proven otherwise', 'If a male (particularly adolescent) presents with acute scrotal pain, torsion is the working diagnosis; imaging or observation must not delay surgical exploration when clinical suspicion exists, and the salvage window is measured in hours from pain onset.', 'Raise an emergency alert with the elapsed-time-from-onset displayed; route directly to surgical review and emergency theatre listing; block pathways that schedule ultrasound as a prerequisite when a capable theatre is available.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_04', 'Obstructed infected kidney requires decompression in hours', 'SURGICAL', 'urology', 'DANGER_SIGN', 'HIGH', 'Obstructed infected kidney requires decompression in hours', 'If imaging or strong clinical evidence shows an obstructing ureteric stone or hydronephrosis together with fever, rigors, or sepsis markers, the patient has an obstructed infected kidney — antibiotics alone cannot sterilise it.', 'Trigger the emergency pathway: sepsis bundle plus urgent decompression decision (JJ stent or nephrostomy, whichever the facility delivers fastest); if neither exists on site, initiate emergency transfer rather than admit-and-observe.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_05', 'Blocked irrigation catheter after prostate or bladder surgery', 'SURGICAL', 'urology', 'DANGER_SIGN', 'HIGH', 'Blocked irrigation catheter after prostate or bladder surgery', 'If a patient on continuous bladder irrigation after prostatectomy or bladder surgery develops absent outflow, suprapubic pain, or a palpably distending bladder, clot retention is presumed — a blocked catheter under irrigation is an emergency, not a routine nursing task.', 'Alert for immediate bedside action: stop irrigation inflow, bladder washout to evacuate clot, and urgent surgical review if washout fails; escalate to theatre for clot evacuation and haemostasis where bleeding continues.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_06', 'Visible haematuria classifies to the urothelial cancer pathway', 'SURGICAL', 'urology', 'CLASSIFICATION', 'MEDIUM', 'Visible haematuria classifies to the urothelial cancer pathway', 'If visible painless haematuria is recorded in an adult (especially over 40, a smoker, or with schistosomiasis exposure), classify to the haematuria work-up pathway: cystoscopy plus upper tract imaging; a bladder mass found classifies to EXPEDITED TURBT at central hospital.', 'Auto-open the haematuria pathway with cystoscopy and imaging orders proposed; flag any visible-haematuria episode older than 6 weeks without a recorded cystoscopy plan; treat bilharzia where ova confirmed without closing the cancer question.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_07', 'Urological prophylaxis targets urinary flora and follows culture', 'SURGICAL', 'urology', 'THERAPY', 'MEDIUM', 'Urological prophylaxis targets urinary flora and follows culture', 'If a urological procedure is booked, prophylaxis is a single intravenous dose at induction targeting gram-negative urinary flora — gentamicin, or cefazolin, or both per local policy and renal function — and is directed by the urine culture result where one exists; established urosepsis converts to a treatment course.', 'Prompt agent selection at induction showing the latest urine culture and renal function; record administration time; suppress prophylaxis prompts when a treatment course is charted.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_08', 'Post-prostatectomy irrigation and haemoglobin surveillance', 'SURGICAL', 'urology', 'MONITORING', 'MEDIUM', 'Post-prostatectomy irrigation and haemoglobin surveillance', 'If a patient is on continuous bladder irrigation after prostatectomy, effluent colour and catheter patency are charted at least hourly for the first 12 hours, with haemoglobin checked per protocol; darkening effluent, haemodynamic change, or falling haemoglobin escalates to surgical review; after transurethral resection, confusion or vomiting raises TUR (dilutional hyponatraemia) syndrome and mandates urgent sodium measurement.', 'Generate hourly irrigation observations for 12 hours then per protocol; alert on darkening effluent, obstruction, haemodynamic triggers, or neurological change; propose sodium check on any post-TUR neurological symptom.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_09', 'Bladder tumour surveillance after TURBT', 'SURGICAL', 'urology', 'FOLLOW_UP', 'MEDIUM', 'Bladder tumour surveillance after TURBT', 'If TURBT histology confirms bladder cancer, non-muscle-invasive disease requires check cystoscopy at 3 months and a risk-stratified ongoing cystoscopic surveillance schedule; muscle-invasive disease routes to MDT for radical treatment decision instead of surveillance.', 'At histology sign-off, auto-book the 3-month check cystoscopy for non-muscle-invasive disease and generate the surveillance schedule; route muscle-invasive results to MDT within 2 weeks; flag any confirmed tumour with no follow-up event booked.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_URO_10', 'Trial of void and flow review close the retention episode', 'SURGICAL', 'urology', 'FOLLOW_UP', 'MEDIUM', 'Trial of void and flow review close the retention episode', 'If a catheter was placed for retention or removed after prostate/urethral surgery, a documented trial of void outcome is required; failed trials route back to the surgical pathway, and successful ones get a flow and symptom review at 4–6 weeks — an episode is not closed by catheter removal alone.', 'Auto-generate the trial-of-void task at catheter removal with outcome capture; book the 4–6 week review on success; re-open the surgical worklist entry on failure.', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/urology-rules.jsonl","rule_key":"SURG-URO-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_01', 'Acute limb ischaemia — threatened limb', 'SURGICAL', 'vascular', 'DANGER_SIGN', 'HIGH', 'Acute limb ischaemia — threatened limb', 'Limb with pain, pallor, pulselessness, coldness AND either sensory loss or muscle weakness/tenderness (Rutherford IIa/IIb pattern)', 'Emergency pathway: anticoagulate on diagnosis per protocol, keep the limb dependent-neutral and warm, nil by mouth, theatre/transfer for revascularisation within the 6-hour warm-ischaemia window; record onset time prominently; fixed mottling with rigid muscles reroutes to amputation counselling, not revascularisation', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-01","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_02', 'Post-revascularisation compartment syndrome and reperfusion injury', 'SURGICAL', 'vascular', 'DANGER_SIGN', 'HIGH', 'Post-revascularisation compartment syndrome and reperfusion injury', 'Revascularisation after more than 4 hours of ischaemia AND (increasing calf pain/tension OR dark urine OR rising potassium)', 'Urgent senior review for fasciotomy if not already done; send potassium and creatine kinase, monitor urine output and colour; alert for arrhythmia from hyperkalaemia; do not attribute new calf pain post-embolectomy to the wound', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-02","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_03', 'Loss of arteriovenous fistula thrill', 'SURGICAL', 'vascular', 'DANGER_SIGN', 'HIGH', 'Loss of arteriovenous fistula thrill', 'Patient with an AV fistula reports absent thrill/buzz, or staff find no thrill or bruit on examination', 'Same-day referral to the access surgeon/dialysis unit — early thrombosis is salvageable within hours; do not schedule to routine clinic; document last-known-patent time', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-03","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_04', 'Diabetic foot severity grading required', 'SURGICAL', 'vascular', 'CLASSIFICATION', 'MEDIUM', 'Diabetic foot severity grading required', 'Diabetic foot ulcer or infection recorded AND no severity grade (Wagner or equivalent local scale) captured', 'Prompt grading at first assessment and at each operative event; grade 3 and above (deep abscess/osteomyelitis/gangrene) routes to same-day surgical review rather than dressing clinic', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-04","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_05', 'Arterial assessment before compression or ulcer surgery', 'SURGICAL', 'vascular', 'DATA_VALIDATION', 'MEDIUM', 'Arterial assessment before compression or ulcer surgery', 'Compression bandaging prescribed or venous ulcer surgery booked AND no arterial assessment recorded (palpable pedal pulses or ankle-brachial index)', 'Block the compression/surgery order until pedal pulses or ABI documented; ABI below 0.8 (or absent pulses) reroutes to arterial work-up — compression over an ischaemic limb causes necrosis', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-05","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_06', 'Ischaemia time captured for vascular trauma', 'SURGICAL', 'vascular', 'DATA_VALIDATION', 'MEDIUM', 'Ischaemia time captured for vascular trauma', 'Vascular injury with ischaemia recorded AND injury time or reperfusion time missing from the operative record', 'Require both timestamps before record completion; auto-compute ischaemia duration and surface it on the post-operative monitoring plan (drives fasciotomy vigilance)', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-06","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_07', 'Heparinisation before arterial clamping', 'SURGICAL', 'vascular', 'THERAPY', 'MEDIUM', 'Heparinisation before arterial clamping', 'Elective/urgent arterial reconstruction or embolectomy operative record completed AND no intra-operative heparin (or documented contraindication) recorded before clamp application', 'Prompt the team to record systemic heparin administration prior to clamping, or the explicit bleeding-risk contraindication that replaced it (with regional/local flush alternative noted)', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-07","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_08', 'Vein-preservation flag for CKD patients', 'SURGICAL', 'vascular', 'THERAPY', 'MEDIUM', 'Vein-preservation flag for CKD patients', 'Patient with CKD stage 4-5 or planned dialysis AND any order for IV cannulation/phlebotomy on the planned access arm (non-dominant forearm/cephalic system)', 'Surface a vein-preservation banner on the patient record: no cannulas, blood draws or blood-pressure cuffs on the flagged arm; suggest dorsum-of-hand or dominant arm alternatives', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-08","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_09', 'Post-revascularisation perfusion observations', 'SURGICAL', 'vascular', 'MONITORING', 'MEDIUM', 'Post-revascularisation perfusion observations', 'Arterial repair, bypass or embolectomy completed within the past 48 hours', 'Schedule perfusion checks (colour, warmth, capillary refill, pedal Doppler signal, pain) hourly for 6 hours then 4-hourly; any lost signal or new pain triggers immediate surgeon notification — early graft/artery thrombosis is salvageable', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-09","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb),
('SURG_VASC_10', 'Amputation aftercare bundle', 'SURGICAL', 'vascular', 'FOLLOW_UP', 'MEDIUM', 'Amputation aftercare bundle', 'Major limb amputation performed AND discharge planned without prosthetic/rehabilitation referral, stump-care instruction, and contralateral-foot review recorded', 'Block discharge checklist completion until physiotherapy/prosthetics referral, stump bandaging education, phantom-pain counselling and an examination of the remaining foot (for diabetics) are documented; book wound review and suture removal at 2-3 weeks', false, true, DATE '9999-01-01', 1, 'ENGINEERING_SEED', 'PENDING_MOHCC_RATIFICATION', NULL, NULL, '[{"source":"docs/clinical/surgical-domain-pack/rule-fragments/vascular-rules.jsonl","rule_key":"SURG-VASC-10","authored_by":"engineering","authored_wave":"SB-4","severity_origin":"LAYER_DEFAULT_NOT_AUTHORED","logic_origin":"PROSE_NOT_EXECUTABLE","pending":"MOHCC_RATIFICATION"}]'::jsonb);

COMMENT ON TABLE clinical.rule_definitions IS
    'Rule governance metadata. Rows whose logic_json and logic_expression are both NULL are inspectable content only and cannot be evaluated; rows whose effective_start lies beyond the operational horizon are not in force. Both are true of the SURG_* surgical seed pack loaded in V300.';
